class TimeoutError(Exception):
    """
    A timeout has occurred.
    """


class TimeoutErrorWithData(TimeoutError):
    """
    A timeout has occurred, data was read so far.
    """

    def __init__(self, data, **kwargs):
        super(TimeoutErrorWithData, self).__init__(**kwargs)
        self.data = data

    def __str__(self):
        return "data=%r" % self.data

    def __repr__(self):
        return "TimeoutErrorWithData(data=%r)" % self.data


class ExecutionError(Exception):
    """
    An execution failed.
    """

    def __init__(self, stdout, stderr, exit_status, **kwargs):
        super(ExecutionError, self).__init__(**kwargs)
        self.stdout = stdout
        self.stderr = stderr
        self.exit_status = exit_status

    def __str__(self):
        return "stdout=%r, stderr=%r, exit_status=%r" % (self.stdout, self.stderr, self.exit_status)

    def __repr__(self):
        return "ExecutionError(stdout=%r, stderr=%r, exit_status=%r)" % (self.stdout, self.stderr, self.exit_status)
